"import sys, json, urllib.request, re; from youtube_transcript_api import YouTubeTranscriptApi; video_id='dQw4w9WgXcQ'; html=urllib.request.urlopen('https://www.youtube.com/watch?v='+video_id).read().decode('utf-8'); title=re.search(r'<title>(.*?)</title>', html).group(1).replace(' - YouTube', ''); transcript=YouTubeTranscriptApi.get_transcript(video_id, languages=['ja', 'en']); text=' '.join([t['text'] for t in transcript]); print(json.dumps({'title':title, 'content':text}))"  
